<?php declare(strict_types=1);session_name('dws_portal');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);session_start();require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();function portal_escape($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}function portal_csrf():string{if(empty($_SESSION['portal_csrf']))$_SESSION['portal_csrf']=bin2hex(random_bytes(32));return $_SESSION['portal_csrf'];}function portal_check_csrf():void{if(!hash_equals($_SESSION['portal_csrf']??'',(string)($_POST['csrf']??''))){http_response_code(419);exit('Invalid security token.');}}function portal_require_user():array{$id=(int)($_SESSION['portal_user_id']??0);if(!$id){header('Location: login.php');exit;}$q=$GLOBALS['db']->prepare('SELECT id,client_id,email,first_name,last_name,is_active FROM client_portal_users WHERE id=? LIMIT 1');$q->execute([$id]);$u=$q->fetch();if(!$u||!(int)$u['is_active']){$_SESSION=[];header('Location: login.php');exit;}return $u;}function portal_log(int $client,int $user,string $type,?string $refType=null,?int $refId=null,?string $description=null):void{$q=$GLOBALS['db']->prepare('INSERT INTO client_portal_activity(client_id,user_id,activity_type,reference_type,reference_id,description) VALUES(?,?,?,?,?,?)');$q->execute([$client,$user,$type,$refType,$refId,$description]);}